    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "set",
      "values": {
        "conveyor_fault": true
      }
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": false
