    },
    {
      "op": "set",
      "values": {
        "conveyor_fault": false
      }
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "pulse",
      "signal": "panel_start",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": true
        }
      ],
      "timeout_s": 5
    },
    {
      "op": "wait",
      "seconds": 2.0
    },
    {
      "op": "pulse",
      "signal": "panel_stop",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait",
      "seconds": 0.3
    }
  ],
  "completion": {
    "all": [
      {
        "signal": "conveyor_run",
        "equals": false
      },
      {
        "signal": "pusher_extend",
        "equals": false
      },
      {
        "signal": "emitter_emit",
        "equals": false
      }
    ],
    "settle_s": 0.3
  },
  "cleanup_inputs": {
    "sensor_low_detect": false,
    "sensor_high_detect": false,
    "pusher_extended": false,
    "pusher_retracted": false,
    "conveyor_fault": false,
    "pusher_fault": false,
    "panel_start": false,
